# This script checks if a given positive integer is a palindrome or not.

# Prompt the user to input numbers and check if they are palindromes.
while (1) {
  print "Enter a positive integer (or press Ctrl+C to exit): ";
  chomp(my $num = <STDIN>);

  # Validate the input
  if ($num =~ /^[1-9]\d*$/) {
    # If the input is valid, check if it's a palindrome
    if (is_palindrome($num)) {
      print "$num is a palindrome.\n";
    } else {
      print "$num is not a palindrome.\n";
    }
  } else {
    # If the input is invalid, prompt the user to enter a valid input.
    print "Invalid input. Please enter a positive integer.\n";
  }
}

# This function checks if a given number is a palindrome or not.
sub is_palindrome {
  my $num = shift;

  # Convert the number to a string
